'use strict';

// MODULES //

var bench = require( '@stdlib/bench' );
var UINT32_MAX = require( '@stdlib/constants/uint32/max' );
var discreteUniform = require( '@stdlib/random/array/discrete-uniform' );
var Uint64 = require( '@stdlib/number/uint64/ctor' );
var format = require( '@stdlib/string/format' );
var pkg = require( './../package.json' ).name;
var parseUint64 = require( './../lib' );


// VARIABLES //

var options = {
	'dtype': 'uint32'
};


// MAIN //

bench( pkg, function benchmark( b ) {
	var values;
	var N;
	var a;
	var i;
	var x;

	N = 100;
	x = discreteUniform( N, 0, UINT32_MAX, options );
	values = [];
	for ( i = 0; i < N; i++ ) {
		a = Uint64.of( x[ i ], x[ (i+1)%N ] );
		values.push( a.toString( 10 ) );
		values.push( '0b'+a.toString( 2 ) );
		values.push( '0o'+a.toString( 8 ) );
		values.push( '0x'+a.toString( 16 ) );
	}

	b.tic();
	for ( i = 0; i < b.iterations; i++ ) {
		a = parseUint64( values[ i % N ] );
		if ( typeof a !== 'object' ) {
			b.fail( 'should return a Uint64 instance' );
		}
	}
	b.toc();
	if ( !( a instanceof Uint64 ) ) {
		b.fail( 'should return a Uint64 instance' );
	}
	b.pass( 'benchmark finished' );
	b.end();
});

bench( format( '%s::radix', pkg ), function benchmark( b ) {
	var radices;
	var values;
	var rad;
	var N;
	var a;
	var i;
	var x;

	N = 100;
	x = discreteUniform( N, 0, UINT32_MAX, options );
	values = [];
	radices = [];
	for ( i = 0; i < N; i++ ) {
		a = Uint64.of( x[ i ], x[ (i+1)%N ] );
		for ( rad = 2; rad <= 36; rad++ ) {
			values.push( a.toString( rad ) );
			radices.push( rad );
		}
	}

	b.tic();
	for ( i = 0; i < b.iterations; i++ ) {
		a = parseUint64( values[ i % N ], radices[ i % N ] );
		if ( typeof a !== 'object' ) {
			b.fail( 'should return a Uint64 instance' );
		}
	}
	b.toc();
	if ( !( a instanceof Uint64 ) ) {
		b.fail( 'should return a Uint64 instance' );
	}
	b.pass( 'benchmark finished' );
	b.end();
});
